export function getRotation(face) {
    switch(face) { case 1: return { x: 0, y: 0 }; case 2: return { x: -90, y: 0 }; case 3: return { x: 0, y: -90 }; case 4: return { x: 0, y: 90 }; case 5: return { x: 90, y: 0 }; case 6: return { x: 180, y: 0 }; }
}

export function calcSpin(curr, targetFace) {
    let tgt = getRotation(targetFace); let nx = curr.x + 1080; let ny = curr.y + 1080;
    nx += (tgt.x - (nx % 360)); ny += (tgt.y - (ny % 360)); return { x: nx, y: ny };
}

export const sleep = ms => new Promise(r => setTimeout(r, ms));

export function getCellCoords(num) {
    let r = Math.floor((num - 1) / 10); let c = (num - 1) % 10; if (r % 2 === 1) { c = 9 - c; }
    return { x: (c * 10) + 5, y: ((9 - r) * 10) + 5 };
}

export let audioCtx = null;
export function initAudio() {
    if (!audioCtx) { const AudioContext = window.AudioContext || window.webkitAudioContext; audioCtx = new AudioContext(); }
    if (audioCtx.state === 'suspended') { audioCtx.resume(); }
}

export function HAP(type) {
    if(!navigator.vibrate) return;
    try {
        if(type === 'click') navigator.vibrate(15);
        if(type === 'step') navigator.vibrate(20);
        if(type === 'dice') navigator.vibrate([15, 30, 15, 30, 15]);
        if(type === 'win') navigator.vibrate([100, 50, 100, 50, 200]);
        if(type === 'error') navigator.vibrate([50, 50, 50]);
    } catch(e) {}
}

export function playClickSound() {
    try {
        HAP('click'); 
        initAudio(); 
        const osc = audioCtx.createOscillator(); 
        const gain = audioCtx.createGain();

        osc.type = 'sine'; 
        osc.frequency.setValueAtTime(900, audioCtx.currentTime);
        osc.frequency.exponentialRampToValueAtTime(1400, audioCtx.currentTime + 0.05);

        gain.gain.setValueAtTime(0.1, audioCtx.currentTime); 
        gain.gain.exponentialRampToValueAtTime(0.01, audioCtx.currentTime + 0.05);

        osc.connect(gain); 
        gain.connect(audioCtx.destination); 

        // CLEANUP: Disconnect node setelah suara selesai dimainkan
        osc.onended = () => {
            osc.disconnect();
            gain.disconnect();
        };

        osc.start(); 
        osc.stop(audioCtx.currentTime + 0.05);
    } catch(e) {}
}

export function playStepSound() {
    try {
        HAP('step'); 
        initAudio(); 
        const osc = audioCtx.createOscillator(); 
        const gain = audioCtx.createGain();

        osc.type = 'triangle'; 
        osc.frequency.setValueAtTime(400, audioCtx.currentTime);
        osc.frequency.exponentialRampToValueAtTime(150, audioCtx.currentTime + 0.1);

        gain.gain.setValueAtTime(0.15, audioCtx.currentTime); 
        gain.gain.linearRampToValueAtTime(0.01, audioCtx.currentTime + 0.1);

        osc.connect(gain); 
        gain.connect(audioCtx.destination); 

        // CLEANUP: Disconnect node setelah suara selesai dimainkan
        osc.onended = () => {
            osc.disconnect();
            gain.disconnect();
        };

        osc.start(); 
        osc.stop(audioCtx.currentTime + 0.1);
    } catch(e) {}
}

export function playDiceSound() {
    try {
        HAP('dice'); 
        initAudio(); 
        let now = audioCtx.currentTime;

        for (let i = 0; i < 6; i++) {
            let delay = i * 0.08; 
            let osc = audioCtx.createOscillator(); 
            let gain = audioCtx.createGain();

            osc.type = 'square'; 
            osc.frequency.setValueAtTime(500 + Math.random() * 500, now + delay);

            gain.gain.setValueAtTime(0.08, now + delay); 
            gain.gain.linearRampToValueAtTime(0.001, now + delay + 0.06);

            osc.connect(gain); 
            gain.connect(audioCtx.destination); 

            // CLEANUP: Disconnect setiap node dadu setelah selesai
            osc.onended = () => {
                osc.disconnect();
                gain.disconnect();
            };

            osc.start(now + delay); 
            osc.stop(now + delay + 0.06);
        }
    } catch(e) {}
}
